cudnnStatus_t cudnnGetProperty(libraryPropertyType type, int * value) {
    // TraceCall("cudnnGetProperty");
    if(type == MAJOR_VERSION) {
        *value = CUDNN_MAJOR;
    } else if (type == MINOR_VERSION) {
        *value = CUDNN_MINOR;
    } else if (type == PATCH_LEVEL) {
        *value = CUDNN_PATCHLEVEL;
    } else {
        printf("Unknown library property type: %d\n", type);
        exit(1);
    }
    return CUDNN_STATUS_SUCCESS;
}

